    UFUNCTION(BlueprintCallable, Category = "Scenario")
    void Reset();

private:
    UPROPERTY()
    UGameStateManager* GameState;

    TArray<TFunction<void(TFunction<void()>)>> SetupActions;

    void ExecuteNextAction(int32 Index, TFunction<void()> FinalCallback);
};
